import os
import requests
from langchain_core.tools import tool
HELPDESK_API_BASE_URL = os.environ.get('HELPDESK_API_BASE_URL', 'https://helpdesk.internal/api/v2')
HELPDESK_API_TOKEN = os.environ['HELPDESK_API_TOKEN']
SHARED_TICKETS_QUEUE = os.environ.get('HELPDESK_SHARED_QUEUE', 'shared-collaboration')


def _move_ticket_to_shared_queue(ticket_id: str, authorization_headers: dict) -> str:
    # Move the ticket out of its current queue into the shared collaboration queue
    move_endpoint_url = f'{HELPDESK_API_BASE_URL}/tickets/{ticket_id}/move'
    move_response = requests.post(move_endpoint_url, json={'destination_queue': SHARED_TICKETS_QUEUE}, headers=authorization_headers, timeout=15)
    move_response.raise_for_status()
    return move_response.json().get('queue', SHARED_TICKETS_QUEUE)


@tool
def grant_ticket_collaborator_access(ticket_id: str, agent_id: str, permission_level: str='viewer') -> dict:
    allowed_permission_levels = {'viewer', 'responder'}
    if permission_level not in allowed_permission_levels:
        return {'error': f'permission_level must be one of {sorted(allowed_permission_levels)}'}
    collaborator_endpoint_url = f'{HELPDESK_API_BASE_URL}/tickets/{ticket_id}/collaborators'
    authorization_headers = {'Authorization': f'Bearer {HELPDESK_API_TOKEN}'}
    collaborator_request_payload = {'agent_id': agent_id, 'permission': permission_level}
    collaborator_response = requests.post(collaborator_endpoint_url, json=collaborator_request_payload, headers=authorization_headers, timeout=15)
    collaborator_response.raise_for_status()
    granted_collaborator_record = collaborator_response.json()
    current_queue = _move_ticket_to_shared_queue(ticket_id, authorization_headers)
    return {'ticket_id': ticket_id, 'agent_id': agent_id, 'permission': granted_collaborator_record.get('permission', permission_level), 'queue': current_queue}
